static List<Vector3> p;static List<Vector2> uv;static List<int> ids;const float X=-115.245f;static float Z(float u){return Mathf.Lerp(-414.0647f,-289.7646f,u);}static float Y(float v){return Mathf.Lerp(27.6664f,45.7f,Mathf.InverseLerp(.026f,.691f,v));}static Vector2 UV(Vector3 q){return new Vector2(Mathf.InverseLerp(-414.0647f,-289.7646f,q.z),Mathf.Lerp(.026f,.691f,Mathf.InverseLerp(27.6664f,45.7f,q.y)));}
