static void Run(){var sc=SceneManager.GetSceneByPath("Assets/Editor/DayNightBackups/Gangstar Final Env.unity");var native=sc.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<MeshFilter>()).Single(f=>f.name=="Building_06_01_Material #26_0");string dir="Assets/Scenes/Oasis/CityHospital/FrontDepth";Directory.CreateDirectory(dir);string bk="FinalEnvironmentRoadBackup/BeforeHospitalFrontDepth";Directory.CreateDirectory(bk);if(!File.Exists(bk+"/Scene.unity"))File.Copy(sc.path,bk+"/Scene.unity");var old=sc.GetRootGameObjects().FirstOrDefault(g=>g.name=="Hospital Front Architectural Detail");if(old)UnityEngine.Object.DestroyImmediate(old);p=new List<Vector3>();uv=new List<Vector2>();ids=new List<int>();Q(new Vector3(X,27.6664f,Z(0)),new Vector3(X,45.7f,Z(0)),new Vector3(X,45.7f,Z(1)),new Vector3(X,27.6664f,Z(1)),true);
