foreach(var a in new[]{new Vector2(0,.012f),new Vector2(.160f,.181f),new Vector2(.358f,.382f),new Vector2(.620f,.642f),new Vector2(.799f,.817f),new Vector2(.879f,.899f),new Vector2(.991f,1)})Box(a.x,a.y,.026f,.691f,.22f);
// Main entrance portal and emergency canopy use their exact atlas regions.
Box(.329f,.342f,.026f,.388f,.65f);Box(.658f,.671f,.026f,.388f,.65f);Box(.342f,.658f,.334f,.380f,1.1f);Box(.023f,.165f,.278f,.318f,.75f);
// Recessed-looking dark glazing mullions, lifted only a few centimetres.
foreach(float u in new[]{.081f,.132f,.233f,.287f,.700f,.752f,.850f})Box(u-.001f,u+.001f,.071f,.678f,.055f);
Box(.184f,.328f,.398f,.409f,.06f);Box(.672f,.878f,.398f,.409f,.06f);
var mesh=new Mesh{name="Hospital Seamless Front and Architectural Relief"};mesh.SetVertices(p);mesh.SetUVs(0,uv);mesh.SetTriangles(ids,0);mesh.RecalculateNormals();mesh.RecalculateBounds();string path=dir+"/Hospital Front Relief.asset";var existing=AssetDatabase.LoadAssetAtPath<Mesh>(path);if(existing){existing.Clear();existing.vertices=mesh.vertices;existing.uv=mesh.uv;existing.triangles=mesh.triangles;existing.normals=mesh.normals;existing.RecalculateBounds();EditorUtility.SetDirty(existing);UnityEngine.Object.DestroyImmediate(mesh);mesh=existing;}else AssetDatabase.CreateAsset(mesh,path);
var root=new GameObject("Hospital Front Architectural Detail");SceneManager.MoveGameObjectToScene(root,sc);root.transform.SetParent(native.transform,true);var mf=root.AddComponent<MeshFilter>();mf.sharedMesh=mesh;var mr=root.AddComponent<MeshRenderer>();mr.sharedMaterial=native.GetComponent<MeshRenderer>().sharedMaterial;mr.shadowCastingMode=ShadowCastingMode.Off;root.isStatic=true;var lod=root.AddComponent<LODGroup>();lod.SetLODs(new[]{new LOD(.008f,new Renderer[]{mr})});lod.RecalculateBounds();PrefabUtility.SaveAsPrefabAsset(root,dir+"/Hospital Front Architectural Detail.prefab");AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(sc);EditorSceneManager.SaveScene(sc);
var cap=typeof(FinalPNGCityDetails).GetMethod("Capture",BindingFlags.NonPublic|BindingFlags.Static);cap.Invoke(null,new object[]{sc,new Vector3(-32,58,-351.9f),new Vector3(-115,36,-351.9f),"Hospital-Front-Depth-Fixed"});cap.Invoke(null,new object[]{sc,new Vector3(-100,33,-299),new Vector3(-115.25f,32,-299),"Hospital-Right-Seam-Fixed"});cap.Invoke(null,new object[]{sc,new Vector3(-91,35,-351.9f),new Vector3(-115.25f,32,-351.9f),"Hospital-Entrance-Depth-Fixed"});File.WriteAllText("FinalEnvironmentRoadReview/HospitalFrontDepthFix.txt","SUCCESS\nContinuous lower façade removes stepped image seam. Original hospital mesh and atlas untouched. Shared material: "+AssetDatabase.GetAssetPath(mr.sharedMaterial)+"\nAdded triangles="+ids.Count/3+"; one combined mesh, one renderer, distance LOD; no added materials/textures/lights/colliders. Existing ground and boundary unchanged. Saved scene and detail prefab.");}}
